contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (reverted && address(c).balance == beforeBalance && c.depositsCount() == beforeCount) ||
            (!reverted && value <= beforeBalance && address(c).balance == beforeBalance - value && address(this).balance >= beforeThis + value && c.depositsCount() == beforeCount)
        );
    }

    receive() external payable {}
}

